import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, step, uniform, time, positionWorld, normalWorld, vec2, Fn, add, mul, sub, clamp } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;

  // ── Visual spec extraction ──────────────────────────────────────────
  const vs = config.intent?.visualSpec ?? {};
  const colors = vs.colors ?? {
    background: '#0b0b10',
    surface: '#16161d',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };
  const gradientStops = vs.gradientStops ?? [
    { at: 0, hex: '#ff4450' },
    { at: 0.55, hex: '#ff2a38' },
    { at: 1, hex: '#c1121f' },
  ];
  const effects = vs.effects ?? {};
  const textItems = config.textContent ?? vs.textContent ?? [];

  // Parse colors into TSL vec3 nodes
  const c1 = new THREE.Color(gradientStops[0].hex);
  const c2 = new THREE.Color(gradientStops[1].hex);
  const c3 = new THREE.Color(gradientStops[2].hex);
  const c1Node = vec3(c1.r, c1.g, c1.b);
  const c2Node = vec3(c2.r, c2.g, c2.b);
  const c3Node = vec3(c3.r, c3.g, c3.b);
  const accentNode = vec3(
    new THREE.Color(colors.accent).r,
    new THREE.Color(colors.accent).g,
    new THREE.Color(colors.accent).b
  );
  const paperNode = vec3(
    new THREE.Color(colors.paper).r,
    new THREE.Color(colors.paper).g,
    new THREE.Color(colors.paper).b
  );
  const stop1 = gradientStops[0].at;
  const stop2 = gradientStops[1].at;
  const stop3 = gradientStops[2].at;

  // ── Helper: create rounded rectangle shape ──────────────────────────
  function createRoundedRectShape(w, h, r) {
    const shape = new THREE.Shape();
    shape.moveTo(-w / 2 + r, -h / 2);
    shape.lineTo(w / 2 - r, -h / 2);
    shape.quadraticCurveTo(w / 2, -h / 2, w / 2, -h / 2 + r);
    shape.lineTo(w / 2, h / 2 - r);
    shape.quadraticCurveTo(w / 2, h / 2, w / 2 - r, h / 2);
    shape.lineTo(-w / 2 + r, h / 2);
    shape.quadraticCurveTo(-w / 2, h / 2, -w / 2, h / 2 - r);
    shape.lineTo(-w / 2, -h / 2 + r);
    shape.quadraticCurveTo(-w / 2, -h / 2, -w / 2 + r, -h / 2);
    return shape;
  }

  const buttonW = 2.6;
  const buttonH = 0.68;
  const cornerR = 0.08;
  const bevelDepth = 0.03;
  const bevelSize = 0.03;

  // ── Backdrop plane (smooth gradient) ────────────────────────────────
  const backdropGeom = new THREE.PlaneGeometry(7, 6);
  const backdropGradientNode = Fn(() => {
    const v = uv().y;
    const t = smoothstep(stop1, stop3, v);
    const color12 = mix(c1Node, c2Node, smoothstep(stop1, stop2, v));
    const color23 = mix(c2Node, c3Node, smoothstep(stop2, stop3, v));
    const final = mix(color12, color23, step(stop2, v));
    return final;
  });
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = backdropGradientNode();
  const backdrop = new THREE.Mesh(backdropGeom, backdropMat);
  backdrop.position.z = -2.5;

  // ── Button group ────────────────────────────────────────────────────
  const buttonGroup = new THREE.Group();

  // Main button shape (extruded with bevel)
  const mainShape = createRoundedRectShape(buttonW, buttonH, cornerR);
  const extrudeSettings = {
    depth: bevelDepth,
    bevelEnabled: true,
    bevelThickness: bevelDepth,
    bevelSize: bevelSize,
    bevelSegments: 1,
  };
  const mainGeom = new THREE.ExtrudeGeometry(mainShape, extrudeSettings);
  mainGeom.computeVertexNormals();

  // Gradient node with hard seam at 50% of face height
  const buttonGradientNode = Fn(() => {
    const v = uv().y;
    // Base gradient: two segments
    const lowColor = mix(c1Node, c2Node, smoothstep(stop1, stop2, v.mul(2)));
    const highColor = mix(c2Node, c3Node, smoothstep(stop2, stop3, sub(v, 0.5).mul(2)));
    const baseColor = mix(lowColor, highColor, step(0.5, v));
    // Hard seam: thin bright line at 0.5
    const seamCenter = 0.5;
    const seamHalf = 0.005;
    const isSeam = step(seamCenter - seamHalf, v).mul(step(v, seamCenter + seamHalf));
    const seamColor = vec3(1, 1, 1); // white seam line
    const final = mix(baseColor, seamColor, isSeam);
    return final;
  });

  const mainMat = new MeshStandardNodeMaterial();
  mainMat.colorNode = buttonGradientNode();
  mainMat.roughness = 0.5;
  mainMat.metalness = 0.35;
  mainMat.clearcoat = 0.22;
  mainMat.envMapIntensity = 1.0;

  const mainMesh = new THREE.Mesh(mainGeom, mainMat);
  buttonGroup.add(mainMesh);

  // ── Perimeter emissive channel (hollow border) ──────────────────────
  const outerW = buttonW + 0.03;
  const outerH = buttonH + 0.03;
  const innerW = buttonW;
  const innerH = buttonH;
  const outerShape = createRoundedRectShape(outerW, outerH, cornerR);
  const innerPath = createRoundedRectShape(innerW, innerH, cornerR);
  outerShape.holes = [innerPath]; // inner shape as a hole

  const borderGeom = new THREE.ExtrudeGeometry(outerShape, { depth: 0.0001, bevelEnabled: false });
  borderGeom.computeVertexNormals();

  const borderMat = new MeshStandardNodeMaterial();
  borderMat.colorNode = vec3(0, 0, 0);
  borderMat.emissiveNode = accentNode;
  borderMat.emissiveIntensity = 1.6;
  borderMat.roughness = 0.5;
  borderMat.metalness = 0.35;
  borderMat.clearcoat = 0.22;

  const borderMesh = new THREE.Mesh(borderGeom, borderMat);
  borderMesh.position.z = bevelDepth + 0.0001; // place on top of front face
  buttonGroup.add(borderMesh);

  // ── Text elements ───────────────────────────────────────────────────
  const labelText = textItems.find(item => item.role === 'cta-label')?.text || 'BEGIN COMMISSION';
  const captionText = textItems.find(item => item.role === 'caption')?.text || 'NO DEPOSIT REQUIRED';

  const labelOpts = {
    fontSize: 0.2,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: 0.08,
  };
  const captionOpts = {
    fontSize: 0.09,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: 0.12,
  };

  const labelMesh = ctx.fontAtlas.createText(labelText, labelOpts);
  labelMesh.position.set(0, 0, bevelDepth + 0.005);
  const captionMesh = ctx.fontAtlas.createText(captionText, captionOpts);
  captionMesh.position.set(0, -0.25, bevelDepth + 0.005);
  buttonGroup.add(labelMesh);
  buttonGroup.add(captionMesh);

  // ── Contact shadow plane ────────────────────────────────────────────
  const shadowGeom = new THREE.PlaneGeometry(buttonW * 1.5, buttonH * 1.5);
  const shadowMat = new MeshBasicNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.35,
    depthWrite: false,
  });
  const shadowMesh = new THREE.Mesh(shadowGeom, shadowMat);
  shadowMesh.position.z = -0.08 - bevelDepth;
  shadowMesh.rotation.x = -Math.PI / 2;
  buttonGroup.add(shadowMesh);

  // ── Lighting ─────────────────────────────────────────────────────────
  const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
  buttonGroup.add(ambientLight);

  const keyLight = new THREE.DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(5, 5, 5);
  buttonGroup.add(keyLight);

  const rimLight = new THREE.DirectionalLight(colors.accent, 0.8);
  rimLight.position.set(-5, 2, 5);
  buttonGroup.add(rimLight);

  const edgeLight = new THREE.DirectionalLight(colors.accent, 1.0);
  edgeLight.position.set(3, -3, 4);
  buttonGroup.add(edgeLight);

  // ── Mount motion: weighted settle ───────────────────────────────────
  buttonGroup.scale.set(1.04, 1.04, 1.04);
  const settleTimeline = gsap.timeline();
  settleTimeline.to(buttonGroup.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });

  // ── Interaction handlers ────────────────────────────────────────────
  let hoverTimeline = null;
  let pressTimeline = null;

  function onPointerEnter() {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(buttonGroup.position, {
      z: 0.06,
      duration: 0.18,
      ease: 'power1.out',
    });
    hoverTimeline.to(borderMat, {
      emissiveIntensity: 2.2,
      duration: 0.18,
      ease: 'power1.out',
    }, 0);
  }

  function onPointerLeave() {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(buttonGroup.position, {
      z: 0,
      duration: 0.18,
      ease: 'power1.out',
    });
    hoverTimeline.to(borderMat, {
      emissiveIntensity: 1.6,
      duration: 0.18,
      ease: 'power1.out',
    }, 0);
  }

  function onPointerDown() {
    if (pressTimeline) pressTimeline.kill();
    pressTimeline = gsap.timeline();
    pressTimeline.to(buttonGroup.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)',
    });
    pressTimeline.to(shadowMesh.scale, {
      x: 0.85,
      y: 0.85,
      duration: 0.12,
      ease: 'back.out(1.7)',
    }, 0);
  }

  function onPointerUp() {
    if (pressTimeline) pressTimeline.kill();
    pressTimeline = gsap.timeline();
    pressTimeline.to(buttonGroup.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.12,
      ease: 'back.out(1.7)',
    });
    pressTimeline.to(shadowMesh.scale, {
      x: 1,
      y: 1,
      duration: 0.12,
      ease: 'back.out(1.7)',
    }, 0);
  }

  buttonGroup.userData.handlers = {
    onPointerEnter,
    onPointerLeave,
    onPointerDown,
    onPointerUp,
  };

  // ── Assemble final group ────────────────────────────────────────────
  const finalGroup = new THREE.Group();
  finalGroup.add(backdrop);
  finalGroup.add(buttonGroup);

  // ── Cleanup ─────────────────────────────────────────────────────────
  finalGroup.userData.cleanup = () => {
    settleTimeline.kill();
    if (hoverTimeline) hoverTimeline.kill();
    if (pressTimeline) pressTimeline.kill();
    backdropGeom.dispose();
    mainGeom.dispose();
    borderGeom.dispose();
    shadowGeom.dispose();
    backdropMat.dispose();
    mainMat.dispose();
    borderMat.dispose();
    shadowMat.dispose();
  };

  return finalGroup;
}
